function checkAutomation(probe, set) {
  const problems = [];
  if (probe.webdriver !== false) problems.push(`navigator.webdriver is ${String(probe.webdriver)}`);
  if (probe.automationProps.length > 0) {
    problems.push(`automation properties: ${probe.automationProps.join(", ")}`);
  }
  if (!probe.hasChrome) problems.push("window.chrome is missing");
  if (probe.plugins === 0) problems.push("no plugins (real Chrome has 5)");
  if (/Headless/i.test(probe.userAgent)) problems.push("the user agent says HeadlessChrome");
  set(
    "automation",
    problems.length === 0 ? "pass" : "fail",
    problems.length === 0 ? `navigator.webdriver is false, window.chrome is there, ${probe.plugins} plugins, no automation properties.` : problems.join("; ")
  );
}
function checkTimezone(probe, set) {
  const ok = probe.timezone === LOCALE.timezone && probe.offset === TOKYO_OFFSET;
  set(
    "timezone",
    ok ? "pass" : "fail",
    ok ? `${probe.timezone} (UTC+09:00), as set.` : `Expected ${LOCALE.timezone} (offset ${TOKYO_OFFSET}), the page saw ${probe.timezone} (offset ${probe.offset}).`
  );
}
function checkLanguage(probe, acceptLanguage, set) {
  const header = Array.isArray(acceptLanguage) ? acceptLanguage.join(",") : acceptLanguage ?? "";
  const problems = [];
  if (probe.language !== LOCALE.languages[0]) {
    problems.push(`navigator.language is ${probe.language}`);
  }
  if (probe.languages.join(",") !== LOCALE.languages.join(",")) {
    problems.push(`navigator.languages is ${probe.languages.join(",")}`);
  }
  if (!header.startsWith(LOCALE.languages[0])) problems.push(`Accept-Language is "${header}"`);
  const intl = probe.intlLocale.split("-")[0] === "de";
  const seen = `navigator.language ${probe.language}, languages ${probe.languages.join(",")}, Accept-Language "${header}", number format ${probe.intlLocale}`;
  if (problems.length > 0) {
    set("language", "fail", `Expected ${LOCALE.languages.join(",")}: ${problems.join("; ")}.`);
  } else if (!intl) {
    set("language", "warn", `${seen}. Dates and numbers still use the computer's language.`);
  } else {
    set("language", "pass", `${seen}.`);
  }
}
function checkPlatform(probe, set) {
  const ok = probe.platform === "Win32" && probe.userAgent.includes("Windows NT") && (probe.uaPlatform === null || probe.uaPlatform === "Windows");
  set(
    "platform",
    ok ? "pass" : "fail",
    `navigator.platform ${probe.platform}, client hints ${probe.uaPlatform ?? "none"}, user agent ${probe.userAgent}`
  );
}

// src/main/browser/extensions.ts
import { promises as fsp4 } from "node:fs";
import { join as join4 } from "node:path";
var GOOGLE_SEARCH = {
  manifest_version: 3,
  name: "Google Search (ProfileHub)",
  version: "1.0.0",
  description: "Searches Google from the address bar.",
  chrome_settings_overrides: {
    search_provider: {
      name: "Google",
      keyword: "google.com",
      search_url: "https://www.google.com/search?q={searchTerms}",
      suggest_url: "https://www.google.com/complete/search?client=chrome&q={searchTerms}",
      favicon_url: "https://www.google.com/favicon.ico",
      encoding: "UTF-8",
      is_default: true
    }
  }
};
var EXTENSIONS = { "google-search": GOOGLE_SEARCH };
var SUPPORTED = ["win32", "darwin"];
async function prepareBrowserExtensions(dir, platform = process.platform) {
  if (!SUPPORTED.includes(platform)) return [];
  const folders = [];
  for (const [name, manifest] of Object.entries(EXTENSIONS)) {
    const folder = join4(dir, name);
    const file = join4(folder, "manifest.json");
    const content = JSON.stringify(manifest, null, 2) + "\n";
    const current = await fsp4.readFile(file, "utf8").catch(() => null);
    if (current !== content) {
      await fsp4.mkdir(folder, { recursive: true });
      await writeFileAtomic(file, content);
    }
    folders.push(folder);
  }
  return folders;
}

// src/main/browser/patches.ts
import { promises as fsp5 } from "node:fs";
import { join as join5 } from "node:path";
import { setTimeout as sleep4 } from "node:timers/promises";
var CANVAS_CRASH = 'Pages that read canvas pixels crash ("Aw, Snap!") in 150.0.7871.186 (issue #94).';
var BINARY_PATCHES = [
  {
    version: "150.0.7871.186",
    platform: "win32-x64",
    file: "chrome.dll",
    offset: 205070406,
    from: "4901c0",
    to: "4989d0",
    reason: CANVAS_CRASH
  },
  {
    version: "150.0.7871.186",
    platform: "linux-x64",
    file: "chrome",
    offset: 254643597,
    from: "4801c6",
    to: "4889d6",
    reason: CANVAS_CRASH
  }
];
async function applyBinaryPatches(dir, version, platform, { patches = BINARY_PATCHES, attempts = 3, retryDelayMs = 500 } = {}) {
  const report = { applied: 0, present: 0, failed: [] };
  for (const patch of patches) {
    if (patch.version !== version || patch.platform !== platform) continue;
    const from = Buffer.from(patch.from, "hex");
    const to = Buffer.from(patch.to, "hex");
    const path = join5(dir, patch.file);
    for (let attempt = 1; ; attempt++) {
      try {
        const current = await readBytes(path, patch.offset, from.length);
        if (current.equals(to)) {
          report.present++;
        } else if (current.equals(from)) {
          await writeBytes(path, patch.offset, to);
          report.applied++;
        } else {
          report.failed.push(
            `${patch.file} has other bytes at 0x${patch.offset.toString(16)} (${current.toString("hex")}).`
          );
        }
        break;
      } catch (error) {
        if (isBusyError(error) && attempt < attempts) {
          await sleep4(retryDelayMs);
          continue;
        }
        report.failed.push(`${patch.file}: ${error.message}`);
        break;
      }
    }
  }
  return report;
}
async function readBytes(path, offset, length) {
  const file = await fsp5.open(path, "r");
  try {
    const buffer = Buffer.alloc(length);
    const { bytesRead } = await file.read(buffer, 0, length, offset);
    return buffer.subarray(0, bytesRead);
  } finally {
    await file.close();
  }
}
async function writeBytes(path, offset, bytes) {
  const file = await fsp5.open(path, "r+");
  try {
    await file.write(bytes, 0, bytes.length, offset);
    await file.sync();
  } finally {
    await file.close();
  }
}

// src/main/browser/checkCli.ts
function checkVerdict(report) {
  const failed = report.checks.filter((check) => check.status === "fail").map((check) => `${check.id}: ${check.detail}`);
  return { passed: failed.length === 0, failed };
}
function formatReport(report) {
  const mark = { pass: "PASS", warn: "WARN", fail: "FAIL" };
  return [
    `ProfileHub Browser ${report.version} (${Math.round(report.durationMs / 1e3)} s)`,
    ...report.checks.map((check) => `  ${mark[check.status]}  ${check.id}  ${check.detail}`)
  ].join("\n");
}
function option(args, name) {
  const index = args.indexOf(`--${name}`);
  return index >= 0 ? args[index + 1] : void 0;
}
async function main(args) {
  const executable = option(args, "exe");
  const version = option(args, "version");
  const reportFile = option(args, "report");
  const extra = (option(args, "extra-args") ?? "").split(" ").filter(Boolean);
  if (!executable || !version) {
    console.error("Usage: browser-check --exe <chrome.exe> --version <version> [--report file]");
    return 2;
  }
  const platform = `${process.platform}-${process.arch}`;
  const patches = await applyBinaryPatches(dirname(executable), version, platform);
  if (patches.applied) console.log(`Known fixes written: ${patches.applied}`);
  for (const reason of patches.failed) console.warn(`Fix not written: ${reason}`);
  const work = await fsp6.mkdtemp(join6(tmpdir(), "ph-check-"));
  try {
    const report = await runBrowserCheck({
      version,
      executable,
      workDir: join6(work, "profiles"),
      ...extra.length > 0 && {
        spawn: (command, list, options) => spawn(command, [...extra, ...list], options)
      },
      extensions: await prepareBrowserExtensions(join6(work, "extensions"))
    });
    console.log(formatReport(report));
    if (reportFile) await fsp6.writeFile(reportFile, `${JSON.stringify(report, null, 2)}
`);
    const verdict = checkVerdict(report);
    if (!verdict.passed) console.error(`Failed:
${verdict.failed.join("\n")}`);
    return verdict.passed ? 0 : 1;
  } finally {
    await fsp6.rm(work, { recursive: true, force: true }).catch(() => {
    });
  }
}

// <stdin>
process.exitCode = await main(process.argv.slice(2));
